from .model_exceptions import ParameterObjectAlreadyExists


class Parameter(object):
    """
    Nidd Parameter representing simpleType object in NIDD.
    By default parameter attributes are not entirely loaded and have NiddParameter.NotLoaded value

    Basic load from Managed Object Basic API (JSON NIDD):
        param_abbr

    Advanced load from Managed Object XML API (XML NIDD):
        value_range
        default_value
        data_type_name
        enum_data_values
        description
        short_desc
        related_functions
        related_features
        modification
    """

    def __init__(self, id, moc_name, package_name, param_abbr, data_type_name, package_id, param_name, status_name,
                 description, related_features, modification, class_name, value_range=None, default_value=None,
                 enum_data_values=None, related_functions=None, creation=None, special=None):
        self.id = id
        self.moc_name = moc_name
        self.package_name = package_name
        self.param_abbr = param_abbr
        self.data_type_name = data_type_name
        self.package_id = package_id
        self.param_name = param_name
        self.status_name = status_name
        self.default_value = default_value
        self.value_range = value_range
        self.class_name = class_name
        self.enum_data_values = enum_data_values
        self.description = description
        self.related_functions = related_functions
        self.related_features = related_features
        self.modification = modification
        self.creation = creation
        self.special = special


class ComplexParameter(Parameter):
    """
    Nidd Parameter representing complexType object in NIDD.
    See NiddParameter doc for more detauls about attributes.

    Contains dictionary map of other NiddParameter objects in parameters attribute
    """

    def __init__(self, id, moc_name, package_name, param_abbr, value_range, data_type_name, package_id, param_name,
                 status_name, description, related_features, modification, class_name, default_value=None,
                 enum_data_values=None, related_functions=None, creation=None, special=None):
        super(ComplexParameter, self).__init__(id=id, moc_name=moc_name, package_name=package_name,
                                               value_range=value_range, data_type_name=data_type_name,
                                               package_id=package_id, param_name=param_name, status_name=status_name,
                                               description=description, related_features=related_features,
                                               modification=modification, class_name=class_name,
                                               default_value=default_value, enum_data_values=enum_data_values,
                                               related_functions=related_functions, param_abbr=param_abbr,
                                               creation=creation, special=special)
        self.parameters = {}

    def add_parameter(self, parameter):
        if parameter.param_abbr in self.parameters:
            raise ParameterObjectAlreadyExists("Parameter object already exists in parameters")

        self.parameters[parameter.param_abbr] = parameter
